package com.ridelink.farepayment.service;
import com.ridelink.farepayment.domain.*;import com.ridelink.farepayment.dto.FareDtos.*;import com.ridelink.farepayment.exception.ApiException;import com.ridelink.farepayment.messaging.PaymentRecorded;import com.ridelink.farepayment.repository.*;import java.math.*;import java.time.Instant;import java.util.UUID;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;
@Service public class FareService {private static final BigDecimal BASE=new BigDecimal("200.00"),PER_KM=new BigDecimal("50.00"),PER_MIN=new BigDecimal("10.00");private final FareRepository fares;private final PaymentRepository payments;private final RabbitTemplate rabbit;public FareService(FareRepository f,PaymentRepository p,RabbitTemplate r){fares=f;payments=p;rabbit=r;}public EstimateResponse estimate(EstimateRequest r){return new EstimateResponse(calculate(r.distanceKm(),r.durationMinutes()),"LKR",BASE,PER_KM,PER_MIN);}public FareResponse finalize(FinalizeRequest r){Fare f=fares.findByRideId(r.rideId()).orElseGet(()->{Fare x=new Fare();x.setId(UUID.randomUUID().toString());x.setRideId(r.rideId());x.setAmount(calculate(r.distanceKm(),r.durationMinutes()));x.setCreatedAt(Instant.now());return fares.save(x);});return new FareResponse(f.getId(),f.getRideId(),f.getAmount(),"LKR",PaymentStatus.PENDING);}public PaymentResponse payment(PaymentRequest r){Fare f=fares.findById(r.fareId()).filter(x->x.getRideId().equals(r.rideId())).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Fare not found for this ride"));Payment p=payments.findByRideId(r.rideId()).orElseGet(()->{Payment x=new Payment();x.setId(UUID.randomUUID().toString());x.setRideId(r.rideId());x.setFareId(f.getId());x.setMethod(r.method());x.setAmount(f.getAmount());x.setStatus("FAIL".equalsIgnoreCase(r.method())?PaymentStatus.FAILED:PaymentStatus.SUCCESS);x.setRecordedAt(Instant.now());x=payments.save(x);rabbit.convertAndSend("ridelink.payment","payment.recorded",new PaymentRecorded(UUID.randomUUID().toString(),"PaymentRecorded",x.getRecordedAt(),x.getRideId(),x.getId(),x.getStatus().name(),x.getAmount(),"LKR"));return x;});return response(p);}public ReceiptResponse receipt(String rideId){Payment p=payments.findByRideId(rideId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Receipt not found"));return new ReceiptResponse("receipt-"+p.getId(),p.getRideId(),p.getId(),p.getAmount(),"LKR",p.getStatus(),p.getRecordedAt());}private BigDecimal calculate(BigDecimal d,BigDecimal m){return BASE.add(d.multiply(PER_KM)).add(m.multiply(PER_MIN)).setScale(2,RoundingMode.HALF_UP);}private PaymentResponse response(Payment p){return new PaymentResponse(p.getId(),p.getRideId(),p.getFareId(),p.getStatus(),p.getAmount(),"LKR",p.getRecordedAt());}}
